import React, { useState, useMemo } from 'react';
import { useApp } from '../context/AppContext';
import useResponsive from '../hooks/useResponsive';
import AddCameraModal from './AddCameraModal';

function AnimatedNumber({ value, color, fontSize }) {
  // Value already comes from context state, so we just render it —
  // the "animation" is the CSS color transition below.
  return (
    <div style={{
      fontSize,
      fontWeight: 700,
      color,
      lineHeight: 1.1,
      transition: 'color .3s'
    }}>
      {value}
    </div>
  );
}

export default function StatsRow() {
  const { stats, wsConnected } = useApp();
  const { isMobile } = useResponsive();
  const [showModal, setShowModal] = useState(false);

  const items = useMemo(() => [
    {
      icon:     '📷',
      label:    'Cameras',
      value:    `${stats.cameras_online || 0} / ${stats.cameras_total || 0}`,
      sub:      'Online',
      subColor: '#3b82f6',
      onClick:  null
    },
    {
      icon:     '🔍',
      label:    'Total Detections',
      value:    stats.total_detections || 0,
      sub:      'Today',
      subColor: '#64748b',
      onClick:  null
    },
    {
      icon:     '🚨',
      label:    'Active Alerts',
      value:    stats.active_alerts || 0,
      sub:      'View All',
      subColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#64748b',
      valColor: (stats.active_alerts || 0) > 0 ? '#ef4444' : '#22c55e',
      onClick:  () => window.dispatchEvent(
        new CustomEvent('navigate', { detail: 'Alerts' })
      )
    },
    {
      icon:     '💚',
      label:    'System Status',
      value:    wsConnected ? 'Healthy' : 'Offline',
      sub:      wsConnected ? 'All Systems Operational' : 'Reconnecting...',
      subColor: '#64748b',
      valColor: wsConnected ? '#22c55e' : '#f97316',
      onClick:  null
    },
  ], [stats, wsConnected]);

  return (
    <>
      <div style={{
        display:             'grid',
        gridTemplateColumns: isMobile ? 'repeat(2, 1fr)' : 'repeat(4, 1fr) auto',
        borderBottom:        '1px solid #1e2d47',
        flexShrink:          0,
        gap:                 '1px',
        background:          '#1e2d47'
      }}>
        {/* Stat cards */}
        {items.map((s, i) => (
          <div key={i} style={{
            background: '#111827',
            padding:    isMobile ? '8px 10px' : '10px 14px',
            display:    'flex',
            alignItems: 'center',
            gap:        isMobile ? 8 : 12
          }}>
            <span style={{ fontSize: isMobile ? 20 : 24, flexShrink: 0 }}>
              {s.icon}
            </span>
            <div>
              <div style={{ fontSize: isMobile ? 9 : 10, color: '#64748b' }}>
                {s.label}
              </div>
              <AnimatedNumber
                value={s.value}
                color={s.valColor || '#fff'}
                fontSize={isMobile ? 16 : 20}
              />
              <div
                style={{
                  fontSize:   isMobile ? 9 : 10,
                  color:      s.subColor,
                  marginTop:  2,
                  cursor:     s.onClick ? 'pointer' : 'default',
                  fontWeight: s.onClick ? 600 : 400,
                  transition: 'color .15s'
                }}
                onClick={s.onClick || undefined}
                onMouseEnter={e => {
                  if (s.onClick) e.currentTarget.style.color = '#fff';
                }}
                onMouseLeave={e => {
                  if (s.onClick) e.currentTarget.style.color = s.subColor;
                }}
              >
                {s.sub}
              </div>
            </div>
          </div>
        ))}

        {/* Add Camera card — 5th column on desktop, full-width row on mobile */}
        <div style={{
          gridColumn:     isMobile ? '1 / -1' : 'auto',
          background:     '#111827',
          padding:        isMobile ? '8px 10px' : '10px 14px',
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center'
        }}>
          <button
            onClick={() => setShowModal(true)}
            style={{
              background:   '#3b82f6',
              color:        '#fff',
              border:       'none',
              padding:      isMobile ? '8px 14px' : '7px 14px',
              borderRadius: 6,
              fontSize:     11,
              fontWeight:   600,
              cursor:       'pointer',
              display:      'flex',
              alignItems:   'center',
              gap:          4,
              whiteSpace:   'nowrap',
              width:        isMobile ? '100%' : 'auto',
              justifyContent: 'center',
              transition:   'background .15s'
            }}
            onMouseEnter={e => e.currentTarget.style.background = '#2563eb'}
            onMouseLeave={e => e.currentTarget.style.background = '#3b82f6'}
          >
            + Add Camera
          </button>
        </div>
      </div>

      {showModal && (
        <AddCameraModal onClose={() => setShowModal(false)} />
      )}
    </>
  );
}
